# 允许旧值出现在**明确标注为旧值**的语境中（回炉说明必须提旧值才能
# 说清改了什么）。判据：该行含「旧值」「已废弃」「原为」「回炉」等标记。
OKCTX = ("旧值", "已废弃", "已作废", "原为", "回炉", "旧口径",
         "仅作对比", "量化该坑", "早期")

def allowed(text: str, pat: str) -> bool:
    """该 pattern 的每一次出现都落在带旧值标记的行内？"""
    return all(any(k in ln for k in OKCTX)
               for ln in text.splitlines() if pat in ln)

for name, pats in stale.items():
    found = []
    for p in pats:
        for fn, t in texts.items():
            if p in t and not allowed(t, p):
                found.append(f"{fn}:{p!r}")
    chk(not found, f"{name} 已清除或仅存于旧值标注语境"
                   + (f"　残留 {found}" if found else ""))
